#!/usr/bin/env python3
"""LaTeX macros and Supplementary tables for the post hoc analyses (DEVIATIONS.md, Nov 12, entry 0f417a48700b). Formats values
already in posthoc.json and posthoc_weights.json; computes no new statistic. Aggregate output only.
Usage: make_posthoc_tables.py POSTHOC.json WEIGHTS.json ABLATIONS.json OUT_MACROS.tex OUT_TABLES.tex"""
import json, sys

FAM = {"qwen3": ("Qwenthree", "Qwen3-0.6B"), "tinyllama": ("Tinyllama", "TinyLlama-1.1B")}
SC = {"agree": "Output agreement", "lineage": "Lineage", "reef": "REEF", "taskcos": "Task-vector cosine", "wo": "Witness Overlap"}
def f2(x): return f"{x:.2f}"
def f3(x): return f"{x:.3f}"
def num(n): return f"{n:,}".replace(",", "{,}")
def pct(a, b): return f"{100 * a / b:.0f}"


def main():
    P, W, A = (json.load(open(p)) for p in sys.argv[1:4]); M = {}; T = []
    G = P["grouped_hub_splits"]
    for fam, (F, _) in FAM.items():
        for col, nm in (("quarter", "Quarter"), ("atype", "Adapter")):
            cells = {k.split("|")[1]: v for k, v in G[col].items() if k.startswith(fam + "|")}
            M[f"ph{nm}Cells{F}"] = str(len(cells)); M[f"ph{nm}Hold{F}"] = str(sum(v["holds"] for v in cells.values()))
            M[f"ph{nm}Max{F}"] = f3(max(v["est"] for v in cells.values())); M[f"ph{nm}Min{F}"] = f3(min(v["est"] for v in cells.values()))
            folds = G[col + "_folds"][fam]; M[f"ph{nm}Folds{F}"] = str(len(folds))
            M[f"ph{nm}FoldMin{F}"] = str(min(folds.values())); M[f"ph{nm}FoldMax{F}"] = str(max(folds.values()))
            fails = [(s, v) for s, v in cells.items() if not v["holds"]]
            for s, v in fails:
                M[f"ph{nm}FailScore{F}"] = SC[s].lower(); M[f"ph{nm}FailEst{F}"] = f3(v["est"]); M[f"ph{nm}FailLo{F}"] = f3(v["lo"]); M[f"ph{nm}FailHi{F}"] = f3(v["hi"])
        hc = P["hub_counts"][fam]["adapter_type"]; M[f"phHubAdapter{F}"] = str(hc.get("adapter", 0)); M[f"phHubFull{F}"] = str(hc.get("full", 0))
        Z = {k.split("|")[1]: v for k, v in P["ties"].items() if k.startswith(fam + "|")}
        M[f"phTieAgreeSib{F}"] = pct(Z["agree"]["tied_within_sibling_reference"], 1); M[f"phTieAgreeInd{F}"] = pct(Z["agree"]["tied_with_independent"], 1)
        M[f"phTieReefSib{F}"] = pct(Z["reef"]["tied_within_sibling_reference"], 1); M[f"phTieLineageSib{F}"] = pct(Z["lineage"]["tied_within_sibling_reference"], 1)
        B = P["cross_by_recipe"]
        for split, sc, nm in (("S5", "taskcos", "SFiveTaskcos"), ("S6", "lineage", "SSixLineage")):
            for at, an in (("full", "Full"), ("adapter", "Adapter")):
                M[f"ph{nm}{an}{F}"] = f2(B[f"{split}|{fam}|{sc}|{at}"]["rate"])
        D = P["distributions"]
        M[f"phLineageHubMedian{F}"] = f3(min(D[f"{fam}|lineage|hub|{a}"]["q50"] for a in ("adapter", "full")))
        M[f"phLineageSibMedianMax{F}"] = f3(max(D[f"{fam}|lineage|sib|{a}"]["q50"] for a in ("adapter", "full")))
        M[f"phTaskcosFullMedian{F}"] = f2(D[f"{fam}|taskcos|sib|full"]["q50"]); M[f"phTaskcosAdapterMedian{F}"] = f3(D[f"{fam}|taskcos|sib|adapter"]["q50"])
        C = P["size_composition"]
        M[f"phSizeLowOnly{F}"] = "yes" if set(C[f"{fam}|size_99"]["by_stratum"]) == {"low"} == set(C[f"{fam}|size_199"]["by_stratum"]) else "no"
        M[f"phSizeBaseRef{F}"] = " and ".join(map(str, C[f"{fam}|size_0"]["ref_sizes"]))
    wf = W["format"]
    for k, nm in (("adapter", "Adapter"), ("full_safetensors", "Safetensors"), ("full_bin", "Bin")):
        M[f"phWc{nm}Fail"] = str(wf[k]["failed"]); M[f"phWc{nm}N"] = str(wf[k]["failed"] + wf[k]["passed"]); M[f"phWc{nm}Pct"] = pct(wf[k]["failed"], wf[k]["failed"] + wf[k]["passed"])
    for k, nm in (("True", "Tag"), ("False", "NoTag")):
        v = W["dataset_tag"][k]; M[f"phWc{nm}Pct"] = pct(v["failed"], v["failed"] + v["passed"])
    q = W["quarter"]; late = [k for k in q if k >= "2026Q2"]; early = [k for k in q if k < "2026Q2"]
    s = lambda ks, f: sum(q[k][f] for k in ks)
    M["phWcLatePct"] = pct(s(late, "failed"), s(late, "failed") + s(late, "passed")); M["phWcEarlyPct"] = pct(s(early, "failed"), s(early, "failed") + s(early, "passed"))
    M["phWcN"] = num(W["n"]); M["phWcPassed"] = num(W["passed"])
    for fam, (F, _) in FAM.items():
        v = W["family"][fam]; M[f"phWcFailPct{F}"] = pct(v["failed"], v["failed"] + v["passed"])
    open(sys.argv[4], "w").write("% Generated by src/make_posthoc_tables.py from data/analysis/posthoc*.json. Do not edit.\n" + "".join(f"\\newcommand{{\\{k}}}{{{v}}}\n" for k, v in sorted(M.items())))
    # Tables.
    T += ["\\begin{table}[ht]\\centering\\footnotesize", "\\caption{\\textbf{Grouped hub splits (post hoc).} The proposed test with the pooled hub reference intersected with independent controls, holding out one upload quarter or one adapter type at a time. Rate, 95\\% publisher-cluster bootstrap interval and whether the H2 thresholds are met (at most 0.08, upper bound at most 0.10). Specified after the confirmatory analysis and labelled post hoc.}\\label{tab:si-grouped}",
          "\\begin{adjustbox}{max width=\\linewidth}\\begin{tabular}{llcccc}\\toprule", "Family & Score & Quarter held out & Holds & Adapter type held out & Holds\\\\\\midrule"]
    for fam, (F, name) in FAM.items():
        for s in SC:
            a, b = G["quarter"][f"{fam}|{s}"], G["atype"][f"{fam}|{s}"]
            T.append(f"{name} & {SC[s]} & {f3(a['est'])} ({f3(a['lo'])}--{f3(a['hi'])}) & {'yes' if a['holds'] else 'no'} & {f3(b['est'])} ({f3(b['lo'])}--{f3(b['hi'])}) & {'yes' if b['holds'] else 'no'}\\\\")
    T += ["\\bottomrule\\end{tabular}\\end{adjustbox}\\end{table}", ""]
    T += ["\\begin{table}[ht]\\centering\\footnotesize", "\\caption{\\textbf{Cross-population rates by adapter type, and score medians (post hoc).} Rate at which the proposed test accused controlled siblings with a hub reference (S5) or hub siblings with a controlled reference (S6), split by whether the suspect is a LoRA adapter or full-weight model, with the per-claimant rates and the median score of each group.}\\label{tab:si-recipe}",
          "\\begin{adjustbox}{max width=\\linewidth}\\begin{tabular}{lllcccc}\\toprule", "Family & Split, score & Suspects & Rate & Per claimant & Median, controlled & Median, hub\\\\\\midrule"]
    for fam, (F, name) in FAM.items():
        for split, s in (("S5", "taskcos"), ("S6", "lineage"), ("S5", "lineage"), ("S6", "taskcos")):
            for at, an in (("full", "full weight"), ("adapter", "LoRA adapter")):
                v = P["cross_by_recipe"][f"{split}|{fam}|{s}|{at}"]; d1 = P["distributions"].get(f"{fam}|{s}|sib|{at}", {}); d2 = P["distributions"].get(f"{fam}|{s}|hub|{at}", {})
                med = lambda d: "--" if d.get("q50") is None or d["q50"] != d["q50"] else f3(d["q50"])
                T.append(f"{name} & {split}, {SC[s].lower()} & {an} & {f2(v['rate'])} & {', '.join(f2(x) for x in v['per_claimant'].values())} & {med(d1)} & {med(d2)}\\\\")
    T += ["\\bottomrule\\end{tabular}\\end{adjustbox}\\end{table}", ""]
    T += ["\\begin{table}[ht]\\centering\\footnotesize", "\\caption{\\textbf{Tied scores.} Fraction of sibling suspects (controlled and hub) whose score equals a score in the independent reference, or equals another score in its same-stratum sibling reference, for the same claimant. Ties count against rejection.}\\label{tab:si-ties}",
          "\\begin{adjustbox}{max width=\\linewidth}\\begin{tabular}{llccc}\\toprule", "Family & Score & Tied with independent & Tied within sibling reference & Distinct values\\\\\\midrule"]
    for fam, (F, name) in FAM.items():
        for s in SC:
            z = P["ties"][f"{fam}|{s}"]; T.append(f"{name} & {SC[s]} & {f3(z['tied_with_independent'])} & {f3(z['tied_within_sibling_reference'])} & {num(z['distinct_values'])} of {num(z['rows'])}\\\\")
    T += ["\\bottomrule\\end{tabular}\\end{adjustbox}\\end{table}", ""]
    T += ["\\begin{table}[ht]\\centering\\footnotesize", "\\caption{\\textbf{Composition of the reference-size ablation.} Suspects evaluated at each setting, by stratum, and the reference sizes used. A size is skipped for a stratum whose reference is smaller, so the 99 and 199 rows contain only low-stratum suspects. Rates are from Supplementary Note 6 (ablation) and the low-stratum breakdown of the same output.}\\label{tab:si-size}",
          "\\begin{adjustbox}{max width=\\linewidth}\\begin{tabular}{llcccc}\\toprule", "Family & Setting & Suspects (high, mid, low) & Reference size & FAR, output agreement & FAR low stratum only\\\\\\midrule"]
    for fam, (F, name) in FAM.items():
        for g, lab in (("base_0", "as analysed"), ("size_49", "49"), ("size_99", "99"), ("size_199", "199")):
            c = P["size_composition"][f"{fam}|{g.replace('base_0', 'size_0')}"]; bs = c["by_stratum"]
            ab = A["grid"][g]; far = ab["far"][f"{fam}|agree"]["est"]; low = ab["far_by_stratum"][f"{fam}|agree|low"]["est"]
            T.append(f"{name} & {lab} & {bs.get('high', 0)}, {bs.get('mid', 0)}, {bs.get('low', 0)} & {', '.join(map(str, c['ref_sizes']))} & {f3(far)} & {f3(low)}\\\\")
    T += ["\\bottomrule\\end{tabular}\\end{adjustbox}\\end{table}", ""]
    T += ["\\begin{table}[ht]\\centering\\footnotesize", "\\caption{\\textbf{Hub siblings that failed the weight check, by metadata.} Counts of models that passed or failed, from census metadata only.}\\label{tab:si-weights}",
          "\\begin{adjustbox}{max width=\\linewidth}\\begin{tabular}{llcc}\\toprule", "Group & Value & Passed & Failed\\\\\\midrule"]
    for col, lab in (("family", "Family"), ("format", "Format"), ("dataset_tag", "Dataset tagged"), ("multi_model_publisher", "Publisher has several models"), ("licence", "Licence"), ("quarter", "Upload quarter")):
        for k, v in W[col].items(): T.append(f"{lab} & {k.replace('_', ' ')} & {v['passed']} & {v['failed']}\\\\")
    T.append("\\midrule")
    for k, v in W["fail_reasons"].items(): T.append(f"Failure reason & {k.replace('_', ' ')} & & {v}\\\\")
    T += ["\\bottomrule\\end{tabular}\\end{adjustbox}\\end{table}"]
    open(sys.argv[5], "w").write("% Generated by src/make_posthoc_tables.py. Do not edit.\n" + "\n".join(T) + "\n")
    print("POSTHOC_TABLES_DONE", len(M))


if __name__ == "__main__":
    main()
